# Surah Al-Hajj (chapter 22) — part 8: ayat 71-78 (IDs 2666-2673)
SURAH = 22

ENTRIES = {
2666: (
"اور وہ اللہ کے سوا اس کی عبادت کرتے ہیں جس کی اس نے کوئی دلیل نازل نہیں کی — اور جس کا انہیں کوئی علم نہیں — اور ظالموں کا کوئی مددگار نہیں",
"""۱۔ بتوں کی عبادت — بغیر دلیل؛ بغیر علم؛ ظالموں کا کوئی مددگار نہیں۔
۲۔ ’’وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَمَا لَيْسَ لَهُم بِهِ عِلْمٌ وَمَا لِلظَّالِمِينَ مِن نَّصِيرٍ‘‘ — اور وہ اللہ کے سوا اس کی عبادت کرتے ہیں جس کی اس نے کوئی دلیل نازل نہیں کی — اور جس کا انہیں کوئی علم نہیں — اور ظالموں کا کوئی مددگار نہیں — یعنی اور وہ اللہ کے سوا اس کی عبادت کرتے ہیں جس کی اس نے کوئی دلیل نازل نہیں کی اور جس کا انہیں کوئی علم نہیں اور ظالموں کا کوئی مددگار نہیں۔
۳۔ عملی سبق: بتوں کی عبادت چھوڑو؛ اللہ کے سوا کسی کی عبادت نہ کرو؛ ظلم سے بچو۔"""
),
2667: (
"اور جب ان پر ہماری واضح آیات پڑھی جائیں تو تم ان لوگوں کے چہروں پر اس انکار کا اثر دیکھتے ہو جنہوں نے کفر کیا — وہ قریب ہیں کہ ان پر ٹوٹ پڑیں جو ان پر ہماری آیات پڑھتے ہیں — کہہ دیجیے کیا میں تمہیں اس سے بدتر کی خبر دوں؟ آگ — اللہ نے اس کا وعدہ کافروں سے کیا ہے — اور کیا برا انجام ہے",
"""۱۔ کفار — آیات پر انکار؛ غصہ؛ آگ؛ اللہ کا وعدہ؛ برا انجام۔
۲۔ ’’وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ تَعْرِفُ فِي وُجُوهِ الَّذِينَ كَفَرُوا الْمُنكَرَ يَكَادُونَ يَسْطُونَ بِالَّذِينَ يَتْلُونَ عَلَيْهِمْ آيَاتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ النَّارُ وَعَدَهَا اللَّهُ الَّذِينَ كَفَرُوا وَبِئْسَ الْمَصِيرُ‘‘ — اور جب ان پر ہماری واضح آیات پڑھی جائیں تو تم ان لوگوں کے چہروں پر اس انکار کا اثر دیکھتے ہو جنہوں نے کفر کیا — وہ قریب ہیں کہ ان پر ٹوٹ پڑیں جو ان پر ہماری آیات پڑھتے ہیں — کہہ دیجیے کیا میں تمہیں اس سے بدتر کی خبر دوں؟ آگ — اللہ نے اس کا وعدہ کافروں سے کیا ہے — اور کیا برا انجام ہے — یعنی اور جب ان پر ہماری واضح آیات پڑھی جائیں تو تم ان لوگوں کے چہروں پر اس انکار کو پہچانتے ہو جنہوں نے کفر کیا وہ قریب ہیں کہ ان پر ٹوٹ پڑیں جو ان پر ہماری آیات پڑھتے ہیں کہہ دیں کیا میں تمہیں اس سے بدتر بتاؤں آگ اللہ نے اس کا کافروں سے وعدہ کیا ہے اور کیا برا انجام ہے۔
۳۔ عملی سبق: اللہ کی آیات کو غور سے سنو؛ کفر سے بچو؛ اس کے عذاب سے ڈرو۔"""
),
2668: (
"اے لوگو ایک مثال بیان کی گئی ہے — اسے غور سے سنو — بے شک وہ جن کی تم اللہ کے سوا عبادت کرتے ہو ایک مکھی بھی پیدا نہیں کر سکتے اگرچہ وہ سب مل جائیں — اور اگر مکھی ان سے کچھ چھین لے تو وہ اس سے چھڑا نہیں سکتے — کمزور ہے طلب کرنے والا اور مطلوب",
"""۱۔ بتوں کا مثال — مکھی؛ پیدا نہ کر سکیں؛ چھڑا نہ سکیں؛ کمزور؛ بے بس۔
۲۔ ’’يَا أَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُ إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَن يَخْلُقُوا ذُبَابًا وَلَوِ اجْتَمَعُوا لَهُ وَإِن يَسْلُبْهُمُ الذُّبَابُ شَيْئًا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ‘‘ — اے لوگو ایک مثال بیان کی گئی ہے — اسے غور سے سنو — بے شک وہ جن کی تم اللہ کے سوا عبادت کرتے ہو ایک مکھی بھی پیدا نہیں کر سکتے اگرچہ وہ سب مل جائیں — اور اگر مکھی ان سے کچھ چھین لے تو وہ اس سے چھڑا نہیں سکتے — کمزور ہے طلب کرنے والا اور مطلوب — یعنی اے لوگو ایک مثال بیان کی گئی ہے اسے غور سے سنو بے شک جو تم اللہ کے سوا پکارتے ہو ایک مکھی بھی پیدا نہیں کر سکتے اگرچہ وہ سب مل جائیں اور اگر مکھی ان سے کچھ چھین لے تو وہ اس سے چھڑا نہیں سکتے کمزور ہے طلب کرنے والا اور مطلوب۔
۳۔ عملی سبق: بتوں کی بے بسی کو پہچانو؛ اللہ کے سوا کسی کی عبادت نہ کرو۔"""
),
2669: (
"انہوں نے اللہ کی قدر نہیں جانی جیسا کہ اس کی قدر جانی جائے — بے شک اللہ طاقتور اور غالب ہے",
"""۱۔ کفار — اللہ کی قدر نہیں جانتے؛ طاقتور؛ غالب؛ اللہ کی عظمت۔
۲۔ ’’مَّا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ‘‘ — انہوں نے اللہ کی قدر نہیں جانی جیسا کہ اس کی قدر جانی جائے — بے شک اللہ طاقتور اور غالب ہے — یعنی انہوں نے اللہ کی قدر نہیں جانی جیسا کہ اس کی قدر جانی جائے بے شک اللہ طاقتور اور غالب ہے۔
۳۔ عملی سبق: اللہ کی قدر جانو؛ اس کی عظمت مانو؛ اس کی عبادت کرو۔"""
),
2670: (
"اللہ فرشتوں میں سے اور لوگوں میں سے اپنے پیغام پہنچانے والے چنتا ہے — بے شک اللہ سننے والا اور دیکھنے والا ہے",
"""۱۔ اللہ — فرشتوں اور لوگوں میں سے پیغام رساں چنتا؛ سنتا؛ دیکھتا۔
۲۔ ’’اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَۃِ رُسُلًا وَمِنَ النَّاسِ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ‘‘ — اللہ فرشتوں میں سے اور لوگوں میں سے اپنے پیغام پہنچانے والے چنتا ہے — بے شک اللہ سننے والا اور دیکھنے والا ہے — یعنی اللہ فرشتوں میں سے اور لوگوں میں سے پیغام رساں چنتا ہے بے شک اللہ سننے والا اور دیکھنے والا ہے۔
۳۔ عملی سبق: اللہ کے پیغام رساں مانو؛ اس کے رسولوںؐ کی پیروی کرو۔"""
),
2671: (
"وہ جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے ہے — اور تمام معاملات اللہ کی طرف لوٹائے جاتے ہیں",
"""۱۔ اللہ کا علم — آگے؛ پیچھے؛ تمام معاملات اللہ کی طرف؛ اللہ کی برتری۔
۲۔ ’’يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ‘‘ — وہ جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے ہے — اور تمام معاملات اللہ کی طرف لوٹائے جاتے ہیں — یعنی وہ جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے اور تمام معاملات اللہ کی طرف لوٹائے جاتے ہیں۔
۳۔ عملی سبق: اللہ کے علم پر ایمان لاؤ؛ اس کے فیصلے پر بھروسہ رکھو۔"""
),
2672: (
"اے ایمان والو رکوع کرو اور سجدہ کرو اور اپنے رب کی عبادت کرو اور نیک کام کرو تاکہ تم کامیاب ہو جاؤ",
"""۱۔ نبیؐ کا حکم — رکوع؛ سجدہ؛ عبادت؛ نیک کام؛ کامیابی۔ (یہ آیت سجدہ کی آیت ہے)
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ‘‘ —اے ایمان والو رکوع کرو اور سجدہ کرو اور اپنے رب کی عبادت کرو اور نیک کام کرو تاکہ تم کامیاب ہو جاؤ۔
۳۔ عملی سبق: نماز پڑھو؛ رکوع و سجدہ کرو؛ نیک کام کرو؛ کامیابی پاؤ۔"""
),
2673: (
"اور اللہ کی راہ میں جیسا جہاد کرنا چاہیے ویسا جہاد کرو — اس نے تمہیں چن لیا — اور اس نے دین میں تم پر کوئی تنگی نہیں رکھی — اپنے باپ ابراہیمؑ کی ملت — اس نے تمہیں اس سے پہلے اور اس میں مسلمان نام دیا تاکہ رسولؐ تم پر گواہ ہوں اور تم لوگوں پر گواہ ہو — پس نماز قائم کرو اور زکوٰۃ دو اور اللہ سے مضبوطی سے وابستہ ہو جاؤ — وہ تمہارا مولا ہے — پس کیا ہی اچھا مولا اور کیا ہی اچھا مددگار ہے",
"""۱۔ جہاد — اللہ کی راہ؛ ابراہیمؑ کی ملت؛ مسلمان؛ گواہی؛ نماز؛ زکوٰۃ؛ اللہ کا ساتھ؛ اچھا مولا۔
۲۔ ’’وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ مِّلَّۃَ أَبِيكُمْ إِبْرَاهِيمَ هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِن قَبْلُ وَفِي هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ فَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلَاكُمْ فَنِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ‘‘ — اور اللہ کی راہ میں جیسا جہاد کرنا چاہیے ویسا جہاد کرو — اس نے تمہیں چن لیا — اور اس نے دین میں تم پر کوئی تنگی نہیں رکھی — اپنے باپ ابراہیمؑ کی ملت — اس نے تمہیں اس سے پہلے اور اس میں مسلمان نام دیا تاکہ رسولؐ تم پر گواہ ہوں اور تم لوگوں پر گواہ ہو — پس نماز قائم کرو اور زکوٰۃ دو اور اللہ سے مضبوطی سے وابستہ ہو جاؤ — وہ تمہارا مولا ہے — پس کیا ہی اچھا مولا اور کیا ہی اچھا مددگار ہے — یعنی اور اللہ کی راہ میں جیسا جہاد کرنا چاہیے ویسا جہاد کرو اس نے تمہیں چن لیا ہے اور اس نے دین میں تم پر کوئی تنگی نہیں رکھی اپنے باپ ابراہیمؑ کی ملت اس نے تمہیں اس سے پہلے اور اس میں مسلمان نام دیا تاکہ رسولؐ تم پر گواہ ہوں اور تم لوگوں پر گواہ ہو پس نماز قائم کرو اور زکوٰۃ دو اور اللہ سے مضبوطی سے وابستہ ہو جاؤ وہ تمہارا مولا ہے پس کیا ہی اچھا مولا اور کیا ہی اچھا مددگار ہے۔
۳۔ عملی سبق: اللہ کی راہ میں جہاد کرو؛ نماز قائم کرو؛ زکوٰۃ دو؛ اللہ سے وابستہ رہو۔"""
),
}
